<?php ob_start(); ?><h1>Suspicious logs</h1><form><input class="input" name="ip" placeholder="IP" value="<?= e($_GET['ip']??'') ?>"> <input class="input" name="uri" placeholder="URI contains" value="<?= e($_GET['uri']??'') ?>"> <input class="input" name="site" placeholder="Site" value="<?= e($_GET['site']??'') ?>"> <select class="input" name="risk"><option value="">Any risk</option><?php foreach(['low','medium','high','critical'] as $r): ?><option value="<?= $r ?>" <?= ($_GET['risk']??'')===$r?'selected':'' ?>><?= $r ?></option><?php endforeach ?></select> <input class="input" name="type" placeholder="Type" value="<?= e($_GET['type']??'') ?>"> <input class="input" type="date" name="date_from" value="<?= e($_GET['date_from']??'') ?>"> <input class="input" type="date" name="date_to" value="<?= e($_GET['date_to']??'') ?>"> <button class="btn">Filter</button> <a class="btn" href="/logs/export.csv?<?= e(http_build_query($_GET)) ?>">Export CSV</a></form><table><tr><th>Risk</th><th>Type</th><th>Site</th><th>IP</th><th>Method</th><th>URI</th><th>Status</th><th>User agent</th><th>Referer</th><th>Raw</th></tr><?php foreach($events as $l): ?><tr><td><span class="badge <?= e($l['risk']) ?>"><?= e($l['risk']) ?></span></td><td><?= e($l['event_type']) ?></td><td><?= e($l['site_name'] ?? '') ?></td><td><?= e($l['ip']) ?></td><td><?= e($l['method']) ?></td><td class="uri-cell"><span title="<?= e($l['uri']) ?>"><?= e(mb_strimwidth($l['uri']??'',0,120,'…')) ?></span></td><td><?= e($l['status_code']) ?></td><td><?= e(mb_strimwidth($l['user_agent']??'',0,80,'…')) ?></td><td><?= e($l['referer']) ?></td><td><pre><?= e(mb_strimwidth($l['raw_line'],0,500,'…')) ?></pre></td></tr><?php endforeach ?></table><?php $content=ob_get_clean(); include base_path('resources/views/layouts/app.php'); ?>
